var $jscomp = $jscomp || {};
$jscomp.scope = {};
$jscomp.createTemplateTagFirstArg = function (b) {
  return (b.raw = b);
};
$jscomp.createTemplateTagFirstArgWithRaw = function (b, a) {
  b.raw = a;
  return b;
};
$jscomp.arrayIteratorImpl = function (b) {
  var a = 0;
  return function () {
    return a < b.length ? { done: !1, value: b[a++] } : { done: !0 };
  };
};
$jscomp.arrayIterator = function (b) {
  return { next: $jscomp.arrayIteratorImpl(b) };
};
$jscomp.makeIterator = function (b) {
  var a = "undefined" != typeof Symbol && Symbol.iterator && b[Symbol.iterator];
  return a ? a.call(b) : $jscomp.arrayIterator(b);
};
var BLOCKED_TIME = "hot_blocker_blocked_time",
  BLOCKED_FORE = "hot_blocker_block_minutes",
  FAIL_COUNTER = "hot_blocker_counter",
  $block = document.getElementById("block");

function incrementCounter(b) {
  var blockMinutes = (window.hotspotConfig && window.hotspotConfig["block-time"] != null) ? parseInt(window.hotspotConfig["block-time"]) : 5;
  var currentVal = getCookieOrNull(FAIL_COUNTER);
  var count = (currentVal != null && !isNaN(parseInt(currentVal))) ? parseInt(currentVal) : 0;
  count = count + 1;
  setCookie(FAIL_COUNTER, count, blockMinutes);
  return count;
}

function checkFailsCount(b, a) {
  var cfg = window.hotspotConfig || {};
  var blockMinutes = cfg["block-time"] != null ? parseInt(cfg["block-time"]) : 5;
  var warnWhen = cfg["warn-when"] != null ? parseInt(cfg["warn-when"]) : 3;
  var tryCount = cfg["try-count"] != null ? parseInt(cfg["try-count"]) : 5;
  var restTries = tryCount - a;

  var warningToast = document.getElementById("blocker-warning-toast");
  var warningMsgEl = document.getElementById("blocker-warning-msg");

  if (a >= tryCount) {
    if (warningToast) warningToast.style.display = "none";
    var h = timeStamp();
    setCookie(BLOCKED_TIME, h, blockMinutes);
    setCookie(BLOCKED_FORE, blockMinutes, blockMinutes);
    redirectToBlockPage();
    return;
  }

  if (a >= warnWhen && restTries > 0) {
    var warnMsg = cfg["warn-message"] || "تبقى لك {{restTryCount}} محاولات قبل أن يتم حظرك لمدة {{blockTime}} دقائق";
    warnMsg = warnMsg.split("{{restTryCount}}").join(restTries + "");
    warnMsg = warnMsg.split("{{tryCount}}").join(tryCount + "");
    warnMsg = warnMsg.split("{{warnWhen}}").join(warnWhen + "");
    warnMsg = warnMsg.split("{{tryCounter}}").join(a + "");
    warnMsg = warnMsg.split("{{blockTime}}").join(blockMinutes + "");

    if (warningToast && warningMsgEl) {
      warningMsgEl.innerText = warnMsg;
      warningToast.style.display = "flex";
    } else {
      var errEl = document.getElementById("error");
      if (errEl) {
        errEl.innerText = (errEl.innerText ? errEl.innerText + " | " : "") + warnMsg;
      }
    }
    showErrorPopup();
  } else {
    if (warningToast) warningToast.style.display = "none";
    showErrorPopup();
  }
}

function resetCounter() {
  setCookie(BLOCKED_TIME, "", 0);
  setCookie(BLOCKED_FORE, "", 0);
  setCookie(FAIL_COUNTER, "", 0);
  try {
    localStorage.removeItem(BLOCKED_TIME);
    localStorage.removeItem(BLOCKED_TIME + "_expires");
    localStorage.removeItem(BLOCKED_FORE);
    localStorage.removeItem(BLOCKED_FORE + "_expires");
    localStorage.removeItem(FAIL_COUNTER);
    localStorage.removeItem(FAIL_COUNTER + "_expires");
    sessionStorage.removeItem(BLOCKED_TIME);
    sessionStorage.removeItem(BLOCKED_FORE);
    sessionStorage.removeItem(FAIL_COUNTER);
  } catch (e) {}
}

function redirectToBlockPage() {
  document.body.classList.add("user-is-blocked");
  document.documentElement.classList.add("user-is-blocked");

  if (typeof hideErrorPopup === "function") hideErrorPopup();

  // Hide all other views
  var loginEl = document.getElementById("login");
  if (loginEl) {
    loginEl.style.display = "none";
    loginEl.classList.add("inactive");
    loginEl.classList.remove("active");
  }
  var statusEl = document.getElementById("status");
  if (statusEl) {
    statusEl.style.display = "none";
    statusEl.classList.remove("active");
  }

  // Close any open modals
  try {
    var modals = document.querySelectorAll(".custom-modal, .modal-overlay, .modal-sheet");
    for (var m = 0; m < modals.length; m++) {
      if (modals[m].id !== "block") {
        modals[m].classList.remove("show");
        modals[m].classList.remove("active");
      }
    }
  } catch (err) {}

  var blockEl = document.getElementById("block");
  if (blockEl) {
    blockEl.style.display = "block";
    blockEl.classList.add("active");
    blockEl.classList.remove("inactive");
    initCountDown(document.querySelector("span[count-down-span]"));
  }
}

function checkIsBlocked() {
  var blockedTime = getCookieOrNull(BLOCKED_TIME);
  if (blockedTime == null) {
    document.body.classList.remove("user-is-blocked");
    document.documentElement.classList.remove("user-is-blocked");
    return false;
  }
  var cfg = window.hotspotConfig || {};
  var blockMinutes = getCookieOrNull(BLOCKED_FORE) || (cfg["block-time"] != null ? cfg["block-time"] : 5);
  var unblockTimestamp = (6e4 * parseInt(blockMinutes)) + parseInt(blockedTime);
  if (timeStamp() >= unblockTimestamp) {
    resetCounter();
    hideBlockPage();
    return false;
  }
  redirectToBlockPage();
  return true;
}

function setCookie(b, a, c) {
  var d = new Date();
  d.setTime(d.getTime() + 6e4 * c);
  var expiresStr = "expires=" + d.toUTCString();
  try {
    document.cookie = b + "=" + a + ";" + expiresStr + ";path=/";
  } catch (e) {}
  try {
    if (c > 0) {
      localStorage.setItem(b, a);
      localStorage.setItem(b + "_expires", d.getTime().toString());
      sessionStorage.setItem(b, a);
    } else {
      localStorage.removeItem(b);
      localStorage.removeItem(b + "_expires");
      sessionStorage.removeItem(b);
    }
  } catch (e) {}
}

function getCookieOrNull(b) {
  try {
    var a = document.cookie.split(";");
    for (var i = 0; i < a.length; i++) {
      var parts = a[i].trim().split("=");
      if (parts[0] === b && parts.length > 1) {
        var val = decodeURIComponent(parts.slice(1).join("="));
        if (val !== "" && val !== "null" && val !== "undefined") return val;
      }
    }
  } catch (e) {}
  try {
    var exp = localStorage.getItem(b + "_expires");
    if (exp && parseInt(exp) < Date.now()) {
      localStorage.removeItem(b);
      localStorage.removeItem(b + "_expires");
      sessionStorage.removeItem(b);
      return null;
    }
    var localVal = localStorage.getItem(b) || sessionStorage.getItem(b);
    if (localVal !== null && localVal !== undefined && localVal !== "" && localVal !== "null") {
      return localVal;
    }
  } catch (e) {}
  return null;
}

function timeStamp() {
  return Math.floor(new Date().getTime());
}

var _blockInterval = null;
function initCountDown(b) {
  if (_blockInterval) clearInterval(_blockInterval);
  if (!b) b = document.querySelector("span[count-down-span]");
  if (b) {
    var a = getCookieOrNull(BLOCKED_TIME);
    if (null === a) {
      showLoginPage();
      hideBlockPage();
    } else {
      var cfg = window.hotspotConfig || {};
      var blockMinutes = getCookieOrNull(BLOCKED_FORE) || (cfg["block-time"] != null ? cfg["block-time"] : 5);
      var c = 6e4 * parseInt(blockMinutes) + parseInt(a);
      var updateDisplay = function () {
        var e = timeStamp();
        var remaining = c - e;
        if (remaining <= 0) {
          if (_blockInterval) clearInterval(_blockInterval);
          resetCounter();
          showLoginPage();
          hideBlockPage();
        } else {
          var minutes = Math.floor((remaining % 36e5) / 6e4);
          var seconds = Math.floor((remaining % 6e4) / 1e3);
          b.innerHTML = minutes + " دقائق و " + seconds + " ثانية";
        }
      };
      updateDisplay();
      _blockInterval = setInterval(updateDisplay, 1e3);
    }
  }
}

function hideBlockPage() {
  document.body.classList.remove("user-is-blocked");
  document.documentElement.classList.remove("user-is-blocked");

  var blockEl = document.getElementById("block");
  if (blockEl) {
    blockEl.style.display = "none";
    blockEl.classList.add("inactive");
    blockEl.classList.remove("active");
  }

  var nav = document.getElementById("bottomNav") || document.querySelector(".bottom-nav-bar");
  if (nav) nav.style.display = "";

  var prevBtn = document.getElementById("quickPreviousCardBtn");
  if (prevBtn) {
    var cookieEnabled = (!window.siteConfig || window.siteConfig.enableHotCookie !== false);
    prevBtn.style.display = cookieEnabled ? "" : "none";
  }
}

document.addEventListener(
  "DOMContentLoaded",
  function () {
    checkIsBlocked();
  },
  false
);
